"use client";
import {useState} from "react";
type Section="Overview"|"Products"|"Businesses"|"Pricing"|"Promotions"|"Customer Engagement"|"Reconciliation"|"Finance Roles";
type ManagementReport={basis:string;kpis:{total_decisions:number;approvals:number;rejections:number;approval_share_percent:number|null};reviewer_activity:{actor:string;action:string;decisions:number;avg_turnaround_hours:number|null}[];monthly_trends:{month:string;action:string;decisions:number}[];actual_sales:null;actual_customer_retention:null;automatic_ordering_enabled:boolean};
type EngagementAudit={basis:string;items:{id:string;template_id:string;action:string;actor:string;note:string;created_at:string;customer_id:string;product_id:string;frequency:string;quantity:number;created_by:string}[];limit:number;offset:number};
type EngagementReport={basis:string;draft_loyalty_enrolments:number;draft_referrals:number;repeat_order_frequency_breakdown:{frequency:string;status:string;template_count:number;planned_quantity_per_cycle:number}[];top_referrers:{referrer_customer_id:string;referral_count:number}[];actual_repeat_orders:null;actual_retention_rate:null;actual_referral_conversions:null;actual_revenue:null};
type EngagementSummary={draft_loyalty_enrolments:number;draft_repeat_order_templates:number;cancelled_repeat_order_templates:number;approved_repeat_order_templates:number;rejected_repeat_order_templates:number;draft_referrals:number;points_enabled:boolean;automatic_ordering_enabled:boolean;referral_rewards_enabled:boolean};
type RepeatOrderPlan={id:string;customer_id:string;product_id:string;quantity:number;frequency:string;status:string;created_by:string;created_at:string;cancelled_by:string|null;cancelled_at:string|null;cancellation_reason:string|null;reviewed_by:string|null;reviewed_at:string|null;review_note:string|null};
type ReferralPlan={id:string;referrer_customer_id:string;referred_customer_id:string;status:string;created_by:string;created_at:string};
type WholesaleReport={basis:string;checkout_enabled:boolean;total_tiers:number;actual_redemptions:null;actual_discount_amount:null;actual_incremental_revenue:null;groups:{status:string;tier_count:number;campaign_count:number;product_count:number;minimum_quantity:number|null;maximum_quantity:number|null}[]};
type WholesaleTierEvent={id:string;actor_subject:string;action:string;created_at:string};
type WholesaleTier={id:string;campaign_id:string;product_id:string;minimum_quantity:number;discount_bps:number;status:string;created_by:string;approved_by:string|null};
type CampaignStockPlan={id:string;campaign_id:string;warehouse_id:string;product_id:string;planned_quantity:number;available_now:number;status:string;created_by:string;reserved:boolean};
type CampaignBudget={id:string;campaign_id:string;limit_amount:string;currency:string;status:string;created_by:string;approved_by:string|null};
type CouponEvent={id:string;actor_subject:string;action:string;created_at:string};
type Coupon={id:string;campaign_id:string;code:string;max_redemptions:number;redemption_count:number;status:string;created_by:string};
type CampaignEvent={id:string;actor_subject:string;action:string;created_at:string};
type Campaign={id:string;code:string;discount_bps:number;minimum_subtotal:string;maximum_discount:string|null;audience:"public"|"business";starts_at:string;ends_at:string;status:string;created_by:string;approved_by:string|null};
type FinanceGrantEvent={subject:string;role:string;action:string;actor:string;created_at:string};
type FinanceGrant={id:string;identity_subject:string;role:string;active:boolean;created_at:string;revoked_at:string|null};
type Investigation={id:string;order_number:string;state:string;amount:string;currency:string;created_at:string;last_reviewed_at:string|null};
type IncidentReview={id:string;actor:string;disposition:string;note:string;created_at:string};
type EmailDelivery={id:string;state:string;attempts:number;created_at:string;last_error:string|null;code:string;severity:string};
type FinanceAlert={id:string;code:string;severity:string;details:string;created_at:string};
type ReconHealth={status:string;alert:boolean;unresolved:number;last_run:{started_at:string;finished_at:string|null;checked:number;updated:number}|null};
type ReconEvent={id:string;outcome:string;remote_status:string|null;actor:string;created_at:string};
type Product={id:string;name:string;sku:string;stock_unit:string};
type Business={id:string;display_name:string;customer_number:string};
type Book={id:string;name:string;code:string;active:boolean;status:string};
const sections:Section[]=["Overview","Products","Businesses","Pricing","Promotions","Customer Engagement","Reconciliation","Finance Roles"];
export default function Admin(){
  const [section,setSection]=useState<Section>("Overview");
  const [engagementSummary,setEngagementSummary]=useState<EngagementSummary|null>(null);
  const [engagementReport,setEngagementReport]=useState<EngagementReport|null>(null);
  const [managementReport,setManagementReport]=useState<ManagementReport|null>(null);
  const [audit,setAudit]=useState<EngagementAudit|null>(null);
  const [auditStatus,setAuditStatus]=useState("");
  const [auditActor,setAuditActor]=useState("");
  const [auditStart,setAuditStart]=useState("");
  const [auditEnd,setAuditEnd]=useState("");
  const [referralPlans,setReferralPlans]=useState<ReferralPlan[]>([]);
  const [repeatPlans,setRepeatPlans]=useState<RepeatOrderPlan[]>([]);
  const [referrerId,setReferrerId]=useState("");
  const [referredId,setReferredId]=useState("");
  const [engagementCustomer,setEngagementCustomer]=useState("");
  const [repeatCustomer,setRepeatCustomer]=useState("");
  const [repeatProduct,setRepeatProduct]=useState("");
  const [repeatQuantity,setRepeatQuantity]=useState("1");
  const [repeatFrequency,setRepeatFrequency]=useState<"weekly"|"monthly">("monthly");
  const [token,setToken]=useState("");
  const [email,setEmail]=useState("");
  const [password,setPassword]=useState("");
  const [products,setProducts]=useState<Product[]>([]);
  const [businesses,setBusinesses]=useState<Business[]>([]);
  const [books,setBooks]=useState<Book[]>([]);
  const [campaigns,setCampaigns]=useState<Campaign[]>([]);
  const [coupons,setCoupons]=useState<Coupon[]>([]);
  const [campaignBudgets,setCampaignBudgets]=useState<CampaignBudget[]>([]);
  const [stockPlans,setStockPlans]=useState<CampaignStockPlan[]>([]);
  const [wholesaleTiers,setWholesaleTiers]=useState<WholesaleTier[]>([]);
  const [wholesaleReport,setWholesaleReport]=useState<WholesaleReport|null>(null);
  const [wholesaleTierEvents,setWholesaleTierEvents]=useState<WholesaleTierEvent[]>([]);
  const [selectedWholesaleTier,setSelectedWholesaleTier]=useState("");
  const [wholesaleCampaign,setWholesaleCampaign]=useState("");
  const [wholesaleProduct,setWholesaleProduct]=useState("");
  const [wholesaleQuantity,setWholesaleQuantity]=useState("10");
  const [wholesaleDiscount,setWholesaleDiscount]=useState("500");
  const [stockCampaign,setStockCampaign]=useState("");
  const [stockWarehouse,setStockWarehouse]=useState("");
  const [stockProduct,setStockProduct]=useState("");
  const [stockQuantity,setStockQuantity]=useState("1");
  const [budgetCampaign,setBudgetCampaign]=useState("");
  const [budgetAmount,setBudgetAmount]=useState("");
  const [couponEvents,setCouponEvents]=useState<CouponEvent[]>([]);
  const [selectedCoupon,setSelectedCoupon]=useState("");
  const [couponCampaign,setCouponCampaign]=useState("");
  const [couponCode,setCouponCode]=useState("");
  const [couponLimit,setCouponLimit]=useState("100");
  const [campaignEvents,setCampaignEvents]=useState<CampaignEvent[]>([]);
  const [selectedCampaign,setSelectedCampaign]=useState("");
  const [campaignCode,setCampaignCode]=useState("");
  const [campaignBps,setCampaignBps]=useState("500");
  const [campaignAudience,setCampaignAudience]=useState<"public"|"business">("business");
  const [campaignMinimum,setCampaignMinimum]=useState("0");
  const [campaignMaximum,setCampaignMaximum]=useState("");
  const [campaignStart,setCampaignStart]=useState("");
  const [campaignEnd,setCampaignEnd]=useState("");
  const [investigations,setInvestigations]=useState<Investigation[]>([]);
  const [financeGrants,setFinanceGrants]=useState<FinanceGrant[]>([]);
  const [financeGrantEvents,setFinanceGrantEvents]=useState<FinanceGrantEvent[]>([]);
  const [grantSubject,setGrantSubject]=useState("");
  const [grantRole,setGrantRole]=useState("finance_viewer");
  const [reconHealth,setReconHealth]=useState<ReconHealth|null>(null);
  const [financeAlerts,setFinanceAlerts]=useState<FinanceAlert[]>([]);
  const [emailDeliveries,setEmailDeliveries]=useState<EmailDelivery[]>([]);
  const [selectedEmail,setSelectedEmail]=useState<string|null>(null);
  const [incidentReviews,setIncidentReviews]=useState<IncidentReview[]>([]);
  const [incidentDisposition,setIncidentDisposition]=useState<"investigating"|"confirmed_sent"|"delivery_unverified">("investigating");
  const [incidentNote,setIncidentNote]=useState("");
  const [incidentSaving,setIncidentSaving]=useState(false);
  const [selectedAttempt,setSelectedAttempt]=useState<string|null>(null);
  const [history,setHistory]=useState<ReconEvent[]>([]);
  const [sku,setSku]=useState("");const [name,setName]=useState("");const [unit,setUnit]=useState("bag");
  const [code,setCode]=useState("");const [bookName,setBookName]=useState("");
  const [selectedBook,setSelectedBook]=useState("");const [selectedProduct,setSelectedProduct]=useState("");
  const [pricingMethod,setPricingMethod]=useState<"fixed_bundle"|"volume_all_units">("fixed_bundle");
  const [tierLines,setTierLines]=useState("1,430\n5,2000\n10,3500");
  const [error,setError]=useState("");const [message,setMessage]=useState("");
  async function call<T>(path:string,method="GET",body?:object,session=token):Promise<T>{
    const r=await fetch("/api/v1"+path,{method,headers:{"content-type":"application/json",...(session?{"authorization":"Bearer "+session}:{})},body:body?JSON.stringify(body):undefined,cache:"no-store"});
    const data=await r.json();if(!r.ok)throw new Error(typeof data.detail==="string"?data.detail:"Request failed");return data as T;
  }
  async function load(sectionName:Section=section,session=token){
    setError("");try{
      if(sectionName==="Products")setProducts(await call<Product[]>("/products","GET",undefined,session));
      if(sectionName==="Businesses")setBusinesses(await call<Business[]>("/admin/businesses/pending","GET",undefined,session));
      if(sectionName==="Finance Roles"){const [grants,events]=await Promise.all([call<FinanceGrant[]>("/admin/finance-roles/grants","GET",undefined,session),call<FinanceGrantEvent[]>("/admin/finance-roles/events","GET",undefined,session)]);setFinanceGrants(grants);setFinanceGrantEvents(events);}
      if(sectionName==="Reconciliation"){const [queue,health,alerts,deliveries]=await Promise.all([call<Investigation[]>("/admin/reconciliation/queue","GET",undefined,session),call<ReconHealth>("/admin/reconciliation/health","GET",undefined,session),call<FinanceAlert[]>("/admin/reconciliation/alerts","GET",undefined,session),call<EmailDelivery[]>("/admin/reconciliation/email-deliveries","GET",undefined,session)]);setInvestigations(queue);setReconHealth(health);setFinanceAlerts(alerts);setEmailDeliveries(deliveries);}
      if(sectionName==="Promotions"){const [items,vouchers,budgets,plans,tiers,report]=await Promise.all([call<Campaign[]>("/admin/campaigns","GET",undefined,session),call<Coupon[]>("/admin/coupons","GET",undefined,session),call<CampaignBudget[]>("/admin/campaign-budgets","GET",undefined,session),call<CampaignStockPlan[]>("/admin/campaign-stock","GET",undefined,session),call<WholesaleTier[]>("/admin/wholesale-promotions","GET",undefined,session),call<WholesaleReport>("/admin/wholesale-promotion-reports/summary","GET",undefined,session)]);setCampaigns(items);setCoupons(vouchers);setCampaignBudgets(budgets);setStockPlans(plans);setWholesaleTiers(tiers);setWholesaleReport(report);}
      if(sectionName==="Customer Engagement"){const [summary,items,referrals,repeats,report]=await Promise.all([call<EngagementSummary>("/admin/customer-engagement/summary","GET",undefined,session),call<Product[]>("/products","GET",undefined,session),call<ReferralPlan[]>("/admin/customer-engagement/referrals","GET",undefined,session),call<RepeatOrderPlan[]>("/admin/customer-engagement/repeat-orders","GET",undefined,session),call<EngagementReport>("/admin/customer-engagement/reports/planning","GET",undefined,session)]);setEngagementReport(report);setEngagementSummary(summary);setProducts(items);setReferralPlans(referrals);setRepeatPlans(repeats);}
      if(sectionName==="Pricing"){setBooks(await call<Book[]>("/admin/price-books","GET",undefined,session));setProducts(await call<Product[]>("/products","GET",undefined,session));}
    }catch(e){setError(e instanceof Error?e.message:"Unable to load");}
  }
  function auditQuery(offset=0){const p=new URLSearchParams({limit:"100",offset:String(offset)});if(auditStatus)p.set("status",auditStatus);if(auditActor.trim())p.set("actor",auditActor.trim());if(auditStart)p.set("start",auditStart);if(auditEnd)p.set("end",auditEnd);return p.toString();}
  async function loadAudit(offset=0){setError("");try{setAudit(await call<EngagementAudit>("/admin/customer-engagement/reports/review-audit?"+auditQuery(offset)));}catch(e){setError(e instanceof Error?e.message:"Unable to load audit");}}
  function reportPeriod(kind:"month"|"previous-month"|"quarter"|"previous-quarter"){const now=new Date();const y=now.getFullYear(),m=now.getMonth();const first=kind==="month"?new Date(y,m,1):kind==="previous-month"?new Date(y,m-1,1):kind==="quarter"?new Date(y,Math.floor(m/3)*3,1):new Date(y,Math.floor(m/3)*3-3,1);const after=kind==="month"?new Date(y,m+1,1):kind==="previous-month"?new Date(y,m,1):kind==="quarter"?new Date(y,Math.floor(m/3)*3+3,1):new Date(y,Math.floor(m/3)*3,1);const iso=(d:Date)=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");setAuditStart(iso(first));setAuditEnd(iso(new Date(after.getFullYear(),after.getMonth(),0)));setManagementReport(null);}
  async function loadManagement(){setError("");try{const q=new URLSearchParams();if(auditStart)q.set("start",auditStart);if(auditEnd)q.set("end",auditEnd);setManagementReport(await call<ManagementReport>("/admin/customer-engagement/reports/management?"+q.toString()));}catch(e){setError(e instanceof Error?e.message:"Unable to load management report");}}
  async function downloadManagementPdf(){setError("");try{const q=new URLSearchParams();if(auditStart)q.set("start",auditStart);if(auditEnd)q.set("end",auditEnd);const r=await fetch("/api/v1/admin/customer-engagement/reports/management.pdf?"+q.toString(),{headers:{"authorization":"Bearer "+token},cache:"no-store"});if(!r.ok)throw Error("Management PDF export failed");const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="customer-engagement-management.pdf";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){setError(e instanceof Error?e.message:"Management PDF export failed");}}
  async function downloadAudit(){setError("");try{const q=new URLSearchParams(auditQuery());q.delete("limit");q.delete("offset");const response=await fetch("/api/v1/admin/customer-engagement/reports/review-audit.csv?"+q.toString(),{headers:{"authorization":"Bearer "+token},cache:"no-store"});if(!response.ok)throw Error("Audit export failed");const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="customer-engagement-review-audit.csv";a.click();URL.revokeObjectURL(url);}catch(e){setError(e instanceof Error?e.message:"Audit export failed");}}
  async function createReferralDraft(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    await call("/admin/customer-engagement/referrals","POST",{referrer_customer_id:referrerId.trim(),referred_customer_id:referredId.trim()});setReferrerId("");setReferredId("");setMessage("Referral recorded as an internal draft; no reward issued.");await load("Customer Engagement");
  }catch(e){setError(e instanceof Error?e.message:"Unable to record referral");}}
  async function reviewRepeatOrder(id:string,decision:"approve"|"reject"){const note=window.prompt("Review note (5–500 characters):");if(note===null)return;if(note.trim().length<5||note.trim().length>500){setError("Provide a review note of 5–500 characters.");return;}setError("");setMessage("");try{await call("/admin/customer-engagement/repeat-orders/"+id+"/review/"+decision,"POST",{note:note.trim()});setMessage("Template "+(decision==="approve"?"approved":"rejected")+" for internal planning only. No customer order created.");await load("Customer Engagement");}catch(e){setError(e instanceof Error?e.message:"Review failed");}}
  async function cancelRepeatOrder(id:string){const reason=window.prompt("Cancellation reason (5–500 characters):");if(reason===null)return;if(reason.trim().length<5||reason.trim().length>500){setError("Please provide a cancellation reason of 5–500 characters.");return;}setError("");setMessage("");try{await call("/admin/customer-engagement/repeat-orders/"+id+"/cancel","POST",{reason:reason.trim()});setMessage("Template cancelled; audit details preserved. No order was placed.");await load("Customer Engagement");}catch(e){setError(e instanceof Error?e.message:"Unable to cancel template");}}
  async function createLoyaltyDraft(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    await call("/admin/customer-engagement/loyalty","POST",{customer_id:engagementCustomer.trim()});setMessage("Customer loyalty enrolment draft created. Points are disabled.");setEngagementCustomer("");await load("Customer Engagement");
  }catch(e){setError(e instanceof Error?e.message:"Unable to create loyalty draft");}}
  async function createRepeatOrderDraft(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    await call("/admin/customer-engagement/repeat-orders","POST",{customer_id:repeatCustomer.trim(),product_id:repeatProduct,quantity:Number(repeatQuantity),frequency:repeatFrequency});setMessage("Repeat-order template saved; no order has been placed.");await load("Customer Engagement");
  }catch(e){setError(e instanceof Error?e.message:"Unable to save repeat-order template");}}
  async function showHistory(id:string){setError("");try{setHistory(await call<ReconEvent[]>("/admin/reconciliation/attempts/"+id+"/history"));setSelectedAttempt(id);}catch(e){setError(e instanceof Error?e.message:"Cannot load audit history");}}
  async function openEmailIncident(id:string){setError("");setMessage("");try{const events=await call<IncidentReview[]>("/admin/notification-incidents/"+id+"/reviews");setSelectedEmail(id);setIncidentReviews(events);setIncidentNote("");setIncidentDisposition("investigating");}catch(e){setError(e instanceof Error?e.message:"Unable to load notification incident");}}
  async function saveIncident(e:React.FormEvent){e.preventDefault();if(!selectedEmail||incidentSaving)return;setError("");setMessage("");setIncidentSaving(true);try{await call("/admin/notification-incidents/"+selectedEmail+"/reviews","POST",{disposition:incidentDisposition,note:incidentNote.trim()});setIncidentReviews(await call<IncidentReview[]>("/admin/notification-incidents/"+selectedEmail+"/reviews"));setIncidentNote("");setMessage("Investigation note saved. No email has been resent.");}catch(e){setError(e instanceof Error?e.message:"Unable to record investigation");}finally{setIncidentSaving(false);}}
  async function requestFinanceGrant(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{await call("/admin/finance-roles/requests","POST",{identity_subject:grantSubject.trim(),role:grantRole});setGrantSubject("");setMessage("Grant requested; a different finance administrator must approve it.");await load("Finance Roles");}catch(e){setError(e instanceof Error?e.message:"Unable to request role");}}
  async function revokeFinanceGrant(id:string){if(!window.confirm("Revoke this finance grant?"))return;setError("");try{await call("/admin/finance-roles/grants/"+id+"/revoke","POST");setMessage("Finance grant revoked.");await load("Finance Roles");}catch(e){setError(e instanceof Error?e.message:"Unable to revoke role");}}
  async function login(e:React.FormEvent){e.preventDefault();setError("");try{const data=await call<{access_token:string}>("/auth/login","POST",{email,password},"");setToken(data.access_token);setPassword("");setMessage("Signed in. Access to staff features is permission controlled.");}catch(e){setError(e instanceof Error?e.message:"Sign in failed");}}
  async function viewWholesaleTierEvents(id:string){setError("");try{setWholesaleTierEvents(await call<WholesaleTierEvent[]>("/admin/wholesale-promotions/"+id+"/events"));setSelectedWholesaleTier(id);}catch(e){setError(e instanceof Error?e.message:"Unable to view wholesale audit history");}}
  async function disableWholesaleTier(id:string){if(!window.confirm("Disable wholesale discount tier? Its audit history remains available."))return;setError("");setMessage("");try{await call("/admin/wholesale-promotions/"+id+"/disable","POST");setMessage("Wholesale tier disabled.");await load("Promotions");}catch(e){setError(e instanceof Error?e.message:"Unable to disable wholesale tier");}}
  async function createWholesaleTier(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    await call("/admin/wholesale-promotions","POST",{campaign_id:wholesaleCampaign,product_id:wholesaleProduct,minimum_quantity:Number(wholesaleQuantity),discount_bps:Number(wholesaleDiscount)});
    setMessage("Wholesale tier saved as a non-payable draft.");await load("Promotions");
  }catch(e){setError(e instanceof Error?e.message:"Unable to create wholesale tier");}}
  async function approveWholesaleTier(id:string){if(!window.confirm("Approve wholesale tier for planning? This does not activate checkout discounts."))return;setError("");setMessage("");try{
    await call("/admin/wholesale-promotions/"+id+"/approve","POST");setMessage("Wholesale tier approved for planning only.");await load("Promotions");
  }catch(e){setError(e instanceof Error?e.message:"Unable to approve wholesale tier");}}
  async function createStockPlan(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    await call("/admin/campaign-stock","POST",{campaign_id:stockCampaign,warehouse_id:stockWarehouse.trim(),product_id:stockProduct.trim(),planned_quantity:Number(stockQuantity)});
    setStockQuantity("1");setMessage("Stock plan saved; no stock has been reserved.");await load("Promotions");
  }catch(e){setError(e instanceof Error?e.message:"Unable to save stock plan");}}
  async function createCampaignBudget(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    await call("/admin/campaign-budgets","POST",{campaign_id:budgetCampaign,limit_amount:budgetAmount});
    setBudgetCampaign("");setBudgetAmount("");setMessage("Campaign budget draft saved. No spending enabled.");await load("Promotions");
  }catch(e){setError(e instanceof Error?e.message:"Unable to create budget");}}
  async function approveCampaignBudget(id:string){if(!window.confirm("Approve this campaign budget as a separate finance administrator? This will not enable spending."))return;
    setError("");setMessage("");try{await call("/admin/campaign-budgets/"+id+"/approve","POST");setMessage("Budget approved for internal planning; checkout spending remains disabled.");await load("Promotions");}
    catch(e){setError(e instanceof Error?e.message:"Unable to approve budget");}}
  async function viewCouponEvents(id:string){setError("");try{
    setCouponEvents(await call<CouponEvent[]>("/admin/coupons/"+id+"/events"));setSelectedCoupon(id);
  }catch(e){setError(e instanceof Error?e.message:"Unable to load coupon history");}}
  async function createCoupon(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    await call("/admin/coupons","POST",{campaign_id:couponCampaign,code:couponCode.trim().toUpperCase(),max_redemptions:Number(couponLimit)});
    setCouponCode("");setMessage("Nonredeemable coupon draft saved.");await load("Promotions");
  }catch(e){setError(e instanceof Error?e.message:"Unable to create coupon");}}
  async function disableCoupon(id:string){if(!window.confirm("Disable this coupon?"))return;setError("");setMessage("");try{
    await call("/admin/coupons/"+id+"/disable","POST");setMessage("Coupon disabled.");await load("Promotions");
  }catch(e){setError(e instanceof Error?e.message:"Unable to disable coupon");}}
  async function viewCampaignEvents(id:string){setError("");try{setCampaignEvents(await call<CampaignEvent[]>("/admin/campaigns/"+id+"/events"));setSelectedCampaign(id);}catch(e){setError(e instanceof Error?e.message:"Cannot load campaign events");}}
  async function disableCampaign(id:string){if(!window.confirm("Disable this campaign? Its history will be retained."))return;
    setError("");setMessage("");try{await call("/admin/campaigns/"+id+"/disable","POST");setMessage("Campaign disabled. Audit history retained.");await load("Promotions");}
    catch(e){setError(e instanceof Error?e.message:"Cannot disable campaign");}}
  async function createCampaign(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    if(!campaignStart||!campaignEnd)throw new Error("Start and end times are required");
    await call("/admin/campaigns","POST",{code:campaignCode.trim(),discount_bps:Number(campaignBps),audience:campaignAudience,
      minimum_subtotal:campaignMinimum,maximum_discount:campaignMaximum||null,
      starts_at:new Date(campaignStart).toISOString(),ends_at:new Date(campaignEnd).toISOString()});
    setCampaignCode("");setMessage("Campaign draft created; checkout remains disabled until separately authorised.");await load("Promotions");
  }catch(e){setError(e instanceof Error?e.message:"Could not create campaign");}}
  async function approveCampaign(id:string){if(!window.confirm("Approve campaign after independently reviewing eligibility and financial terms?"))return;
    setError("");setMessage("");try{await call("/admin/campaigns/"+id+"/approve","POST");setMessage("Campaign approved for internal records only. Checkout remains disabled.");await load("Promotions");}
    catch(e){setError(e instanceof Error?e.message:"Campaign approval failed");}}
  async function createProduct(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{await call("/admin/products","POST",{sku,name,stock_unit:unit});setSku("");setName("");setMessage("Product created");await load("Products");}catch(e){setError(e instanceof Error?e.message:"Unable to save");}}
  async function createBook(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{await call("/admin/price-books","POST",{code,name:bookName});setCode("");setBookName("");setMessage("Inactive price book created");await load("Pricing");}catch(e){setError(e instanceof Error?e.message:"Unable to save");}}
  async function approve(id:string){if(!window.confirm("Confirm business verification was completed for this applicant?"))return;try{await call("/businesses/"+id+"/approve","POST");setMessage("Business marked approved");await load("Businesses");}catch(e){setError(e instanceof Error?e.message:"Approval failed");}}
  async function createPriceTiers(e:React.FormEvent){e.preventDefault();setError("");setMessage("");try{
    const tiers=tierLines.trim().split(/\\r?\\n/).map((line,i)=>{const values=line.split(",").map(v=>v.trim());if(values.length!==2 || !/^\\d+$/.test(values[0]) || !/^\\d+(\\.\\d{1,4})?$/.test(values[1]))throw new Error("Invalid tier on line "+(i+1)+". Use quantity,price.");return {minimum_quantity:Number(values[0]),...(pricingMethod==="fixed_bundle"?{bundle_price:values[1]}:{unit_price:values[1]})}});
    if(!selectedBook||!selectedProduct)throw new Error("Select a price book and product");
    await call("/admin/price-books/"+selectedBook+"/items","POST",{product_id:selectedProduct,method:pricingMethod,tiers});
    setMessage("Draft pricing tiers saved. Approval is still required.");await load("Pricing");
  }catch(e){setError(e instanceof Error?e.message:"Unable to create price tiers");}}
  async function transitionBook(id:string,action:"approve"|"publish"){setError("");setMessage("");try{
    await call("/admin/price-books/"+id+"/"+action,"POST");setMessage("Price book "+(action==="approve"?"approved":"published")+" successfully");await load("Pricing");
  }catch(e){setError(e instanceof Error?e.message:"Request failed");}}
  return <><header><small>LESOTHO FLOUR MILLS</small><h1>Operations Administration</h1></header><main>
  {!token?<section className="panel"><h2>Staff sign in</h2><p>Only provisioned staff accounts can administer company records.</p><form onSubmit={login}><label>Email</label><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/><label>Password</label><input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/><button>Sign in</button></form></section>:<>
    <nav aria-label="Administration sections">{sections.map(s=><button key={s} aria-current={section===s?"page":undefined} onClick={()=>{setSection(s);setError("");setMessage("");void load(s)}}>{s}</button>)}<button onClick={()=>{setToken("");setMessage("");setProducts([]);setBusinesses([]);setBooks([]);setInvestigations([]);setHistory([]);setSelectedAttempt(null)}}>Sign out</button></nav>
    {section==="Overview"&&<div className="grid"><section className="panel"><h2>Products</h2><p>Maintain the authoritative catalogue.</p></section><section className="panel"><h2>Businesses</h2><p>Review new wholesale applications.</p></section><section className="panel"><h2>Price books</h2><p>Configure price schedules before publishing.</p></section></div>}
    {section==="Products"&&<><section className="panel"><h2>Add product</h2><form onSubmit={createProduct}><label>SKU</label><input value={sku} onChange={e=>setSku(e.target.value)} required/><label>Product name</label><input value={name} onChange={e=>setName(e.target.value)} required/><label>Stock unit</label><select value={unit} onChange={e=>setUnit(e.target.value)}><option value="bag">Bag</option><option value="kg">Kilogram</option><option value="unit">Unit</option></select><button>Create product</button></form></section><section className="panel"><h2>Product catalogue</h2><button onClick={()=>void load("Products")}>Refresh</button><ul className="listing">{products.map(p=><li key={p.id}><b>{p.name}</b><span>{p.sku} · {p.stock_unit}</span></li>)}</ul></section></>}
    {section==="Businesses"&&<section className="panel"><h2>Pending business applications</h2><p>Confirm registration evidence outside this screen before approval. Formal verification evidence workflow is still pending.</p><button onClick={()=>void load("Businesses")}>Refresh</button><ul className="listing">{businesses.map(b=><li key={b.id}><span>{b.display_name} · {b.customer_number}</span><button onClick={()=>void approve(b.id)}>Approve</button></li>)}</ul></section>}
    {section==="Reconciliation"&&<section className="panel"><h2>Payment investigation queue</h2>{reconHealth&&<div role="status"><strong>Reconciliation health: {reconHealth.status}</strong><p>{reconHealth.alert?"Attention required":"No current health alerts"} · {reconHealth.unresolved} unresolved attempts</p><p>Last worker run: {reconHealth.last_run?new Date(reconHealth.last_run.started_at).toLocaleString():"Never"}</p></div>}<p>Read-only review of interrupted or unresolved IthutePay checkout attempts. A provider status is not settlement confirmation.</p><button onClick={()=>void load("Reconciliation")}>Refresh queue</button><h3>Email delivery investigations</h3>{emailDeliveries.length===0?<p>No email delivery attempts recorded.</p>:<ul className="listing">{emailDeliveries.map(d=><li key={d.id}><b>{d.code} · {d.state} · {d.attempts} attempt(s)</b><span>{new Date(d.created_at).toLocaleString()} {d.last_error?" · "+d.last_error:""}</span>{["sending","uncertain","failed"].includes(d.state)&&<button onClick={()=>void openEmailIncident(d.id)}>Review incident</button>}</li>)}</ul>}{selectedEmail&&<section><h3>Notification incident review</h3><p>Outbox record: {selectedEmail}</p><h4>Immutable investigation history</h4>{incidentReviews.length===0?<p>No investigation notes recorded.</p>:<ul className="listing">{incidentReviews.map(r=><li key={r.id}><b>{r.disposition} · {r.actor}</b><span>{new Date(r.created_at).toLocaleString()} · {r.note}</span></li>)}</ul>}<form onSubmit={saveIncident}><label>Investigation classification</label><select value={incidentDisposition} onChange={e=>setIncidentDisposition(e.target.value as "investigating"|"confirmed_sent"|"delivery_unverified")}><option value="investigating">Investigating</option><option value="confirmed_sent">Reported sent (requires independent evidence)</option><option value="delivery_unverified">Delivery unverified</option></select><label>Investigation note</label><textarea rows={4} minLength={10} maxLength={2000} required value={incidentNote} onChange={e=>setIncidentNote(e.target.value)}/><button type="submit" disabled={incidentSaving||incidentNote.trim().length<10}>{incidentSaving?"Saving…":"Save investigation note"}</button></form><p>Notes never trigger a resend or change the original delivery status.</p></section>}<p>Email delivery status cannot confirm that a recipient read the message. Uncertain outcomes require review before any retry.</p><h3>Operational alerts</h3>{financeAlerts.length===0?<p>No persisted alerts.</p>:<ul className="listing">{financeAlerts.map(a=><li key={a.id}><b>{a.severity.toUpperCase()} · {a.code}</b><span>{a.details} · {new Date(a.created_at).toLocaleString()}</span></li>)}</ul>}<p>{investigations.length} unresolved attempts shown (maximum 100).</p><ul className="listing">{investigations.map(a=><li key={a.id}><b>{a.order_number}</b><span>{a.currency} {a.amount} · {a.state} · {new Date(a.created_at).toLocaleString()}</span><button onClick={()=>void showHistory(a.id)}>Audit history</button></li>)}</ul>{selectedAttempt&&<section><h3>Reconciliation audit history</h3><p>Attempt: {selectedAttempt}</p>{history.length===0?<p>No observations recorded yet.</p>:<ul className="listing">{history.map(e=><li key={e.id}><b>{e.outcome}</b><span>{e.remote_status??"Status unavailable"} · {new Date(e.created_at).toLocaleString()} · {e.actor}</span></li>)}</ul>}</section>}<p>Manual payment confirmation, charge retries and warehouse release are intentionally unavailable here.</p></section>}
    {section==="Finance Roles"&&<section className="panel"><h2>Finance role administration</h2><p>Only currently authorised finance administrators can access this screen. Grants require independent approval; there is no automatic initial administrator.</p><button onClick={()=>void load("Finance Roles")}>Refresh grants</button><h3>Immutable permission change history</h3>{financeGrantEvents.length===0?<p>No finance grant history recorded.</p>:<ul className="listing">{financeGrantEvents.map((event,i)=><li key={event.subject+event.created_at+i}><b>{event.action} · {event.role}</b><span>{event.subject} · {event.actor} · {new Date(event.created_at).toLocaleString()}</span></li>)}</ul>}<h3>Current role grants</h3>{financeGrants.length===0?<p>No grants returned.</p>:<ul className="listing">{financeGrants.map(g=><li key={g.id}><b>{g.identity_subject} · {g.role}</b><span>{g.active?"Active":"Revoked"} · {new Date(g.created_at).toLocaleString()}</span>{g.active&&<button onClick={()=>void revokeFinanceGrant(g.id)}>Revoke</button>}</li>)}</ul>}<form onSubmit={requestFinanceGrant}><h3>Request a finance role</h3><label>Employee identity subject</label><input value={grantSubject} onChange={e=>setGrantSubject(e.target.value)} required minLength={2} maxLength={255}/><label>Requested role</label><select value={grantRole} onChange={e=>setGrantRole(e.target.value)}><option value="finance_viewer">Finance Viewer</option><option value="finance_reviewer">Finance Reviewer</option><option value="finance_admin">Finance Administrator</option></select><button type="submit">Submit for independent review</button></form><p>Grant approvals are not available from this screen until verified identity membership and audit controls are completed.</p></section>}
    {section==="Promotions"&&<><section className="panel"><h2>Wholesale promotion planning report</h2><p>Internal planning statistics only. Actual redemptions, discount spending and incremental revenue are not available because checkout promotions remain disabled.</p><p><b>Total planned tiers:</b> {wholesaleReport?.total_tiers??"Not loaded"}</p><ul className="listing">{wholesaleReport?.groups.map(g=><li key={g.status}><b>{g.status}</b><span>{g.tier_count} tiers · {g.campaign_count} campaigns · {g.product_count} distinct products · Quantity breaks {g.minimum_quantity??"—"} to {g.maximum_quantity??"—"}</span></li>)}</ul></section><section className="panel"><h2>Wholesale quantity discounts</h2><p>For business-audience campaigns only. Finance approval does not publish prices or activate checkout discounts.</p><ul className="listing">{wholesaleTiers.map(t=><li key={t.id}><span><b>{campaigns.find(c=>c.id===t.campaign_id)?.code??t.campaign_id}</b> · {products.find(p=>p.id===t.product_id)?.name??t.product_id} · From {t.minimum_quantity} units · {(t.discount_bps/100).toFixed(2)}% discount · {t.status} · Prepared by {t.created_by}</span>{t.status==="draft"&&<button onClick={()=>void approveWholesaleTier(t.id)}>Approve tier</button>}{t.status!=="disabled"&&<button onClick={()=>void disableWholesaleTier(t.id)}>Disable tier</button>}<button onClick={()=>void viewWholesaleTierEvents(t.id)}>Audit history</button></li>)}</ul>{selectedWholesaleTier&&<section><h3>Wholesale tier audit history</h3><ul className="listing">{wholesaleTierEvents.map(event=><li key={event.id}><b>{event.action}</b><span>{event.actor_subject} · {new Date(event.created_at).toLocaleString()}</span></li>)}</ul>{wholesaleTierEvents.length===0&&<p>No events recorded.</p>}</section>}{wholesaleTiers.length===0&&<p>No wholesale tiers yet.</p>}<form onSubmit={createWholesaleTier}><h3>Create wholesale discount draft</h3><label>Business campaign</label><select required value={wholesaleCampaign} onChange={e=>setWholesaleCampaign(e.target.value)}><option value="">Choose business campaign</option>{campaigns.filter(c=>c.audience==="business"&&c.status!=="disabled").map(c=><option key={c.id} value={c.id}>{c.code}</option>)}</select><label>Product</label><select required value={wholesaleProduct} onChange={e=>setWholesaleProduct(e.target.value)}><option value="">Choose product</option>{products.map(p=><option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select><label>Minimum quantity</label><input type="number" min="2" step="1" max="1000000" required value={wholesaleQuantity} onChange={e=>setWholesaleQuantity(e.target.value)}/><label>Discount (basis points; 500 = 5%)</label><input type="number" min="1" max="10000" step="1" required value={wholesaleDiscount} onChange={e=>setWholesaleDiscount(e.target.value)}/><button type="submit">Save wholesale draft</button></form></section><section className="panel"><h2>Promotion stock planning</h2><p>Plans compare against available stock, but never reserve inventory or authorise fulfilment. Recheck stock at allocation time.</p><ul className="listing">{stockPlans.map(plan=><li key={plan.id}><span><b>{campaigns.find(c=>c.id===plan.campaign_id)?.code??plan.campaign_id}</b> · Product {products.find(p=>p.id===plan.product_id)?.name??plan.product_id} · Warehouse {plan.warehouse_id} · Planned {plan.planned_quantity} · Available now {plan.available_now} {plan.available_now<plan.planned_quantity?"(below plan)":""}</span></li>)}</ul>{stockPlans.length===0&&<p>No stock plans recorded.</p>}<form onSubmit={createStockPlan}><h3>Create non-reserving stock plan</h3><label>Campaign</label><select required value={stockCampaign} onChange={e=>setStockCampaign(e.target.value)}><option value="">Choose campaign</option>{campaigns.filter(c=>c.status!=="disabled").map(c=><option key={c.id} value={c.id}>{c.code}</option>)}</select><label>Product</label><select required value={stockProduct} onChange={e=>setStockProduct(e.target.value)}><option value="">Choose product</option>{products.map(p=><option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select><label>Warehouse ID</label><input required value={stockWarehouse} onChange={e=>setStockWarehouse(e.target.value)} placeholder="Warehouse UUID"/><label>Planned quantity</label><input type="number" min="1" max="1000000" step="1" required value={stockQuantity} onChange={e=>setStockQuantity(e.target.value)}/><button type="submit">Save non-reserving plan</button></form></section><section className="panel"><h2>Campaign budgets</h2><p>Finance-controlled budget planning. Approval does not authorise discount spending or checkout redemptions.</p><ul className="listing">{campaignBudgets.map(b=><li key={b.id}><span><b>{campaigns.find(c=>c.id===b.campaign_id)?.code??b.campaign_id}</b> · {b.currency} {b.limit_amount} · {b.status} · Prepared by {b.created_by}</span>{b.status==="draft"&&<button onClick={()=>void approveCampaignBudget(b.id)}>Approve budget</button>}</li>)}</ul>{campaignBudgets.length===0&&<p>No budgets recorded.</p>}<form onSubmit={createCampaignBudget}><h3>Create draft budget</h3><label>Campaign</label><select value={budgetCampaign} onChange={e=>setBudgetCampaign(e.target.value)} required><option value="">Choose campaign</option>{campaigns.filter(c=>c.status!=="disabled"&&!campaignBudgets.some(b=>b.campaign_id===c.id)).map(c=><option key={c.id} value={c.id}>{c.code}</option>)}</select><label>Budget limit (LSL)</label><input type="number" min="0.01" step="0.01" value={budgetAmount} onChange={e=>setBudgetAmount(e.target.value)} required/><button type="submit">Save draft budget</button></form></section><section className="panel"><h2>Coupon inventory</h2><p>Coupons are internal drafts only. They cannot be redeemed or used at checkout.</p><ul className="listing">{coupons.map(c=><li key={c.id}><span><b>{c.code}</b> · {c.status} · {c.redemption_count}/{c.max_redemptions} redemptions · Campaign {campaigns.find(p=>p.id===c.campaign_id)?.code??c.campaign_id}</span>{c.status!=="disabled"&&<button onClick={()=>void disableCoupon(c.id)}>Disable coupon</button>}<button onClick={()=>void viewCouponEvents(c.id)}>Audit history</button></li>)}</ul>{selectedCoupon&&<section><h3>Coupon audit history</h3><p>Coupon: {coupons.find(c=>c.id===selectedCoupon)?.code??selectedCoupon}</p>{couponEvents.length===0?<p>No recorded actions.</p>:<ul className="listing">{couponEvents.map(event=><li key={event.id}><b>{event.action}</b><span>{event.actor_subject} · {new Date(event.created_at).toLocaleString()}</span></li>)}</ul>}</section>}{coupons.length===0&&<p>No coupons recorded.</p>}<form onSubmit={createCoupon}><h3>Create coupon draft</h3><label>Campaign</label><select value={couponCampaign} onChange={e=>setCouponCampaign(e.target.value)} required><option value="">Choose campaign</option>{campaigns.filter(c=>c.status!=="disabled").map(c=><option key={c.id} value={c.id}>{c.code} ({c.status})</option>)}</select><label>Coupon code</label><input value={couponCode} onChange={e=>setCouponCode(e.target.value.toUpperCase())} pattern="[A-Z0-9_-]{4,64}" minLength={4} maxLength={64} required/><label>Maximum planned redemptions</label><input type="number" min="1" max="1000000" step="1" value={couponLimit} onChange={e=>setCouponLimit(e.target.value)} required/><button type="submit">Save nonredeemable draft</button></form></section><section className="panel"><h2>Promotion campaigns</h2><p>Draft and review promotional offers. Finance approval is required, and discounts are not connected to checkout.</p><button onClick={()=>void load("Promotions")}>Refresh campaigns</button><ul className="listing">{campaigns.map(c=><li key={c.id}><span><b>{c.code}</b> · {c.discount_bps/100}% · {c.audience}<br/>{c.status} · minimum LSL {c.minimum_subtotal} · {new Date(c.starts_at).toLocaleDateString()}–{new Date(c.ends_at).toLocaleDateString()}</span>{c.status==="draft"&&<button onClick={()=>void approveCampaign(c.id)}>Request approval action</button>}{c.status!=="disabled"&&<button onClick={()=>void disableCampaign(c.id)}>Disable</button>}<button onClick={()=>void viewCampaignEvents(c.id)}>Audit history</button></li>)}</ul>{selectedCampaign&&<section><h3>Campaign audit history</h3><p>Campaign: {selectedCampaign}</p><ul className="listing">{campaignEvents.map(event=><li key={event.id}><b>{event.action}</b><span>{event.actor_subject} · {new Date(event.created_at).toLocaleString()}</span></li>)}</ul>{campaignEvents.length===0&&<p>No audit events found.</p>}</section>}{campaigns.length===0&&<p>No campaigns returned or you do not have access.</p>}</section><section className="panel"><h2>Create draft campaign</h2><form onSubmit={createCampaign}><label>Campaign code</label><input value={campaignCode} onChange={e=>setCampaignCode(e.target.value)} pattern="[A-Za-z0-9_-]+" minLength={3} maxLength={80} required/><label>Discount (basis points; 500 = 5%)</label><input type="number" min="0" max="10000" step="1" value={campaignBps} onChange={e=>setCampaignBps(e.target.value)} required/><label>Customer audience</label><select value={campaignAudience} onChange={e=>setCampaignAudience(e.target.value as "public"|"business")}><option value="business">Approved businesses</option><option value="public">Public customers</option></select><label>Minimum subtotal (LSL)</label><input type="number" min="0" step="0.01" value={campaignMinimum} onChange={e=>setCampaignMinimum(e.target.value)} required/><label>Maximum discount (LSL, optional)</label><input type="number" min="0" step="0.01" value={campaignMaximum} onChange={e=>setCampaignMaximum(e.target.value)}/><label>Starts at (local time)</label><input type="datetime-local" value={campaignStart} onChange={e=>setCampaignStart(e.target.value)} required/><label>Ends at (local time)</label><input type="datetime-local" value={campaignEnd} onChange={e=>setCampaignEnd(e.target.value)} required/><button type="submit">Save draft campaign</button></form><p>Approval requires a different finance administrator. No customer price or order total is changed by this screen.</p></section></>}
    {section==="Customer Engagement"&&<><section className="panel"><h2>Customer engagement planning</h2><p>Draft records only. No reward points, customer credits or automatic orders are activated.</p><p><b>Draft loyalty enrolments:</b> {engagementSummary?.draft_loyalty_enrolments??"Not loaded"} · <b>Draft repeat-order templates:</b> {engagementSummary?.draft_repeat_order_templates??"Not loaded"} · <b>Cancelled:</b> {engagementSummary?.cancelled_repeat_order_templates??"Not loaded"} · <b>Approved (planning):</b> {engagementSummary?.approved_repeat_order_templates??"Not loaded"} · <b>Rejected:</b> {engagementSummary?.rejected_repeat_order_templates??"Not loaded"}</p><button onClick={()=>void load("Customer Engagement")}>Refresh summary</button></section><section className="panel"><h2>Customer engagement planning report</h2><p>Planning-only figures. No completed orders, retention rates, conversion figures or revenue are inferred from draft records.</p><p><b>Actual revenue:</b> Unavailable · <b>Retention rate:</b> Unavailable · <b>Referral conversions:</b> Unavailable</p><h3>Recurring-order frequency breakdown</h3><ul className="listing">{(engagementReport?.repeat_order_frequency_breakdown??[]).map(g=><li key={g.frequency+g.status}><span>{g.frequency} · {g.status} · {g.template_count} templates · {g.planned_quantity_per_cycle} units per planned cycle</span></li>)}</ul><h3>Referral attribution (top 20)</h3><ul className="listing">{(engagementReport?.top_referrers??[]).map(r=><li key={r.referrer_customer_id}><span>{r.referrer_customer_id} · {r.referral_count} draft referral(s)</span></li>)}</ul></section><section className="panel"><h2>Management intelligence — planning reviews</h2><p>Reviewer decisions, average time from template creation to review, and monthly review trends. These figures do not measure customer purchases, sales or retention.</p><p><button onClick={()=>reportPeriod("month")}>This month</button><button onClick={()=>reportPeriod("previous-month")}>Previous month</button><button onClick={()=>reportPeriod("quarter")}>This quarter</button><button onClick={()=>reportPeriod("previous-quarter")}>Previous quarter</button></p><button onClick={()=>void loadManagement()}>Refresh management report</button><p>{managementReport?<>Planning decisions: <b>{managementReport.kpis.total_decisions}</b> · Approved: <b>{managementReport.kpis.approvals}</b> · Rejected: <b>{managementReport.kpis.rejections}</b> · Approval share: <b>{managementReport.kpis.approval_share_percent===null?"N/A":managementReport.kpis.approval_share_percent+"%"}</b></>:"Select a reporting period and refresh."}</p><button onClick={()=>void downloadManagementPdf()}>Download PDF report</button><button onClick={()=>window.print()}>Print management page</button><h3>Reviewer performance</h3><ul className="listing">{(managementReport?.reviewer_activity??[]).map(r=><li key={r.actor+r.action}><span>{r.actor} · {r.action} · {r.decisions} decision(s) · Average turnaround: {r.avg_turnaround_hours===null?"Unavailable":r.avg_turnaround_hours+" hours"}</span></li>)}</ul><h3>Monthly decision trend</h3><ul className="listing">{(managementReport?.monthly_trends??[]).map(r=><li key={r.month+r.action}><span>{r.month} · {r.action} · {r.decisions} decisions</span></li>)}</ul></section><section className="panel"><h2>Planning review audit</h2><p>Search approved and rejected internal plans. CSV exports are capped at 5,000 records; they never represent actual orders or revenue.</p><label>Decision</label><select value={auditStatus} onChange={e=>setAuditStatus(e.target.value)}><option value="">All decisions</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select><label>Reviewer identity</label><input value={auditActor} onChange={e=>setAuditActor(e.target.value)} placeholder="Exact reviewer subject"/><label>From date</label><input type="date" value={auditStart} onChange={e=>setAuditStart(e.target.value)}/><label>Through date</label><input type="date" value={auditEnd} onChange={e=>setAuditEnd(e.target.value)}/><button onClick={()=>void loadAudit(0)}>Search audit</button><button onClick={()=>void downloadAudit()}>Export filtered CSV</button><ul className="listing">{(audit?.items??[]).map(e=><li key={e.id}><span>{new Date(e.created_at).toLocaleString()} · {e.action} · Reviewer: {e.actor} · Customer: {e.customer_id} · {e.note}</span></li>)}</ul>{audit&&<p>Showing {audit.items.length} items from offset {audit.offset}. <button disabled={audit.offset===0} onClick={()=>void loadAudit(Math.max(0,audit.offset-100))}>Previous</button><button disabled={audit.items.length<100} onClick={()=>void loadAudit(audit.offset+100)}>Next</button></p>}</section><section className="panel"><h2>Referral planning</h2><p>No referral points, cash or coupons are issued. Referral plans are internal drafts.</p><p><b>Draft referrals:</b> {engagementSummary?.draft_referrals??"Not loaded"}</p><ul className="listing">{referralPlans.map(p=><li key={p.id}><span>{p.referrer_customer_id} referred {p.referred_customer_id} · {p.status}</span></li>)}</ul><form onSubmit={createReferralDraft}><h3>Record customer referral</h3><label>Referring customer UUID</label><input value={referrerId} onChange={e=>setReferrerId(e.target.value)} required/><label>Referred customer UUID</label><input value={referredId} onChange={e=>setReferredId(e.target.value)} required/><button type="submit">Save referral draft</button></form></section><section className="panel"><h2>Loyalty enrolment draft</h2><form onSubmit={createLoyaltyDraft}><label>Customer ID (UUID)</label><input value={engagementCustomer} onChange={e=>setEngagementCustomer(e.target.value)} required placeholder="Existing customer UUID"/><button type="submit">Create enrolment draft</button></form></section><section className="panel"><h2>Repeat-order template draft</h2><form onSubmit={createRepeatOrderDraft}><label>Customer ID (UUID)</label><input value={repeatCustomer} onChange={e=>setRepeatCustomer(e.target.value)} required placeholder="Existing customer UUID"/><label>Product</label><select required value={repeatProduct} onChange={e=>setRepeatProduct(e.target.value)}><option value="">Select product</option>{products.map(p=><option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select><label>Quantity</label><input type="number" min="1" max="1000000" step="1" required value={repeatQuantity} onChange={e=>setRepeatQuantity(e.target.value)}/><label>Frequency</label><select value={repeatFrequency} onChange={e=>setRepeatFrequency(e.target.value as "weekly"|"monthly")}><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select><button type="submit">Save template draft</button></form><p>Templates do not create orders or reserve stock.</p></section><section className="panel"><h2>Repeat-order planning register</h2><p>Finance-controlled draft cancellation with recorded reason and actor. Cancellation does not affect orders, payments or stock.</p><ul className="listing">{repeatPlans.map(p=><li key={p.id}><span>{p.customer_id} · {products.find(item=>item.id===p.product_id)?.name??p.product_id} · {p.quantity} · {p.frequency} · {p.status}{p.cancelled_at?` · Cancelled by ${p.cancelled_by} on ${new Date(p.cancelled_at).toLocaleString()} · ${p.cancellation_reason}`:""}{p.reviewed_at?` · Reviewed by ${p.reviewed_by} on ${new Date(p.reviewed_at).toLocaleString()} · ${p.review_note}`:""}</span>{p.status==="draft"&&<button type="button" onClick={()=>void reviewRepeatOrder(p.id,"approve")}>Approve planning</button>}{p.status==="draft"&&<button type="button" onClick={()=>void reviewRepeatOrder(p.id,"reject")}>Reject planning</button>}{p.status==="draft"&&<button type="button" onClick={()=>void cancelRepeatOrder(p.id)}>Cancel draft</button>}</li>)}</ul></section></>}
    {section==="Pricing"&&<><section className="panel"><h2>Create price book</h2><p>Books are created inactive and cannot yet be published to customer checkout.</p><form onSubmit={createBook}><label>Code</label><input value={code} onChange={e=>setCode(e.target.value)} required/><label>Book name</label><input value={bookName} onChange={e=>setBookName(e.target.value)} required/><button>Create inactive book</button></form></section><section className="panel"><h2>Price books</h2><button onClick={()=>void load("Pricing")}>Refresh</button><ul className="listing">{books.map(b=><li key={b.id}><b>{b.name}</b><span>{b.code} · {b.status??(b.active?"Published":"Draft")}</span>{b.status==="draft"&&<button onClick={()=>void transitionBook(b.id,"approve")}>Approve</button>}{b.status==="approved"&&<button onClick={()=>void transitionBook(b.id,"publish")}>Publish</button>}</li>)}</ul><p>Prices remain drafts until approved and published. A different authorised employee must publish approved prices.</p><form onSubmit={createPriceTiers}><h3>Add draft quantity tiers</h3><label>Price book</label><select value={selectedBook} onChange={e=>setSelectedBook(e.target.value)} required><option value="">Select book</option>{books.filter(b=>!b.active && (!b.status || b.status==="draft")).map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><label>Product</label><select value={selectedProduct} onChange={e=>setSelectedProduct(e.target.value)} required><option value="">Select product</option>{products.map(p=><option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select><label>Pricing method</label><select value={pricingMethod} onChange={e=>setPricingMethod(e.target.value as "fixed_bundle"|"volume_all_units")}><option value="fixed_bundle">Fixed bundles</option><option value="volume_all_units">Volume price per bag</option></select><label>Quantity, price (one per line)</label><textarea aria-label="Quantity price tiers" rows={5} value={tierLines} onChange={e=>setTierLines(e.target.value)} required/><p>Example values only; enter approved draft prices, not assumed selling prices.</p><button type="submit">Save draft tiers</button></form></section></>}
  </>}
  {error&&<p className="error" role="alert">{error}</p>}{message&&<p className="success" role="status">{message}</p>}
  </main></>;
}
